var i=`0664-puff-puff`;var t=`world-0664`;var a=`NG`;var s=`western-africa`;var o=8;var u=90;var r={en:`Puff-Puff`,ua:`Пафф-пафф`};var l={en:`Puff-Puff is a Nigeria classic prepared with all-purpose flour, instant yeast. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Пафф-пафф, страва кухні країни Нігерія зі складниками: пшеничне борошно універсальне, інстантні дріжджі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 60 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 60 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:60,i:[[`all-purpose-flour`,470,`g`],[`instant-yeast`,8,`g`],[`white-granulated-sugar`,85,`g`],[`water`,300,`ml`],[`table-salt`,4,`g`],[`ground-nutmeg`,3,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[]},{en:`Drop spoonfuls of risen yeast dough into 170°C oil and turn until puffed, golden and thoroughly cooked inside.`,ua:`Опускайте ложками підняте дріжджове тісто в олію 170°C та перевертайте до пухкості, золотавості й повної готовності всередині.`,t:[`deep-frying`],m:22,i:[[`sunflower-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,35,`g`]]}];var g={slug:i,id:t,country:`NG`,region:s,servings:8,minutes:90,title:r,text:l,steps:d};export{a as country,g as default,t as id,u as minutes,s as region,o as servings,i as slug,d as steps,l as text,r as title};